    "versets_count": 110,
    "theme": "Quatre récits sur l'épreuve de la foi — les Gens de la Caverne endormis des siècles, l'homme aux deux jardins, Moïse et le mystérieux al-Khiḍr, et Dhū l-Qarnayn — liés par une même leçon : la foi éprouvée par le temps, la richesse, le savoir et le pouvoir",
    "note_pedagogique": "La sourate recommandée à la récitation du vendredi, réputée protéger de l'imposteur eschatologique (le Dajjāl). Elle enchaîne quatre récits d'épreuve : de jeunes croyants réfugiés dans une caverne où Dieu les endort trois siècles ; un riche orgueilleux dont le jardin est ravagé ; Moïse suivant al-Khiḍr et ne pouvant supporter l'apparente injustice de ses actes ; et le roi juste Dhū l-Qarnayn bâtissant une digue contre Gog et Magog.",
